import numpy as np
from collections import Counter
import math

class BagOfWords:
    def __init__(self):
        self.vocab = {}

    def fit(self, documents):
        '''Build vocabulary'''
        all_words = set()
        for doc in documents:
            all_words.update(doc.split())
        self.vocab = {word: i for i, word in enumerate(sorted(all_words))}

    def transform(self, document):
        '''Convert to BoW vector'''
        vector = np.zeros(len(self.vocab))
        for word in document.split():
            if word in self.vocab:
                vector[self.vocab[word]] += 1
        return vector

class TFIDF:
    def __init__(self):
        self.vocab = {}
        self.idf = {}

    def fit(self, documents):
        '''Compute vocabulary and IDF'''
        # Vocabulary
        all_words = set()
        for doc in documents:
            all_words.update(doc.split())
        self.vocab = {word: i for i, word in enumerate(sorted(all_words))}

        # IDF: log(N / df)
        N = len(documents)
        word_doc_count = Counter()

        for doc in documents:
            unique_words = set(doc.split())
            for word in unique_words:
                word_doc_count[word] += 1

        for word in self.vocab:
            df = word_doc_count[word]
            self.idf[word] = math.log(N / (1 + df))

    def transform(self, document):
        '''Convert to TF-IDF vector'''
        # Term frequency
        tf = Counter(document.split())

        # TF-IDF
        vector = np.zeros(len(self.vocab))
        for word, count in tf.items():
            if word in self.vocab:
                idx = self.vocab[word]
                vector[idx] = count * self.idf[word]

        return vector

# Example
docs = [
    "the cat sat on the mat",
    "the dog sat on the log",
    "cats and dogs are enemies"
]

# BoW
bow = BagOfWords()
bow.fit(docs)
vec = bow.transform("the cat sat")
print(f"BoW: {vec}")

# TF-IDF
tfidf = TFIDF()
tfidf.fit(docs)
vec = tfidf.transform("the cat sat")
print(f"TF-IDF: {vec}")
print(f"Notice: 'the' has lower weight (common word)")
